// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;

    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(c));
        amount = bound(amount, 1, 1 ether);
        address owner = address(this); // Owner is the deployer of c
        vm.deal(owner, amount);
        uint256 balBefore = address(c).balance;
        vm.prank(owner);
        c.Command{value: amount}(target, hex"");
        assertTrue(address(c).balance == balBefore);
    }
}
